          lessonsCount: c.modules?.reduce((sum, m) => sum + (m.lessons?.length || 0), 0) || 0
        }));
      },
      error: err => {
        console.error('Failed to load courses', err);
        this.courses = [];
      }
    });
  }
  loadPlans() {
    this.apiService.get('/api/subscription-plans').subscribe({
      next: data => {
        this.plans = data;
      },
      error: err => {
        console.error('Failed to load subscription plans', err);
        this.plans = [];
      }
    });
  }
  getPlanName(planId) {
    if (!planId) return '';
    const plan = this.plans.find(p => p.id === planId);
    return plan ? plan.name : '';
  }
  onThumbError(event) {
    event.target.style.display = 'none';
  }
  openCourseModal() {
    this.editingCourse = null;
    this.errorMessage = '';
    this.courseForm = {
      title: '',
      description: '',
      thumbnailUrl: '',
      instructorId: null,
      planId: null,
      modules: []
    };
    this.showModal = true;
  }
  editCourse(course) {
    this.editingCourse = course;
    this.errorMessage = '';
    this.apiService.get(`/api/courses/${course.id}`).subscribe({
      next: data => {
        this.courseForm = {
          title: data.title,
          description: data.description || '',
          thumbnailUrl: data.thumbnailUrl || '',
          instructorId: data.instructorId,
          planId: data.planId || null,
          modules: data.modules?.map(m => ({
            title: m.title,
            description: m.description || '',
            orderIndex: m.orderIndex || 0,
            lessons: m.lessons?.map(l => ({
              title: l.title,
              content: l.content || '',
              videoUrl: l.videoUrl || '',
              orderIndex: l.orderIndex || 0,
              durationMinutes: l.durationMinutes || 0
            })) || []
          })) || []
        };
        this.showModal = true;
      },
      error: err => {
        console.error('Failed to load course details', err);
        this.errorMessage = 'Failed to load course details';
      }
    });
  }
  closeModal(event) {
    this.showModal = false;
    this.editingCourse = null;
    this.errorMessage = '';
  }
  addModule() {
    this.courseForm.modules.push({
      title: '',
      description: '',
      orderIndex: this.courseForm.modules.length,
      lessons: []
