  }
  removeModule(index) {
    this.courseForm.modules.splice(index, 1);
  }
  addLesson(module) {
    module.lessons.push({
      title: '',
      content: '',
      videoUrl: '',
      orderIndex: module.lessons.length,
      durationMinutes: 0
    });
  }
  removeLesson(module, index) {
    module.lessons.splice(index, 1);
  }
  saveCourse() {
