          this.saving = false;
          this.loadCourses();
          this.closeModal();
        },
        error: err => {
          this.saving = false;
          console.error('Failed to create course', err);
          this.errorMessage = 'Failed to create course. ' + (err.error?.message || 'Please check the details and try again.');
